create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz default now());
create table if not exists public.products(id bigint generated by default as identity primary key,slug text unique not null,name text not null,description text default '',local_image text default '',image_url text default '',page_url text not null,available boolean not null default true,prices jsonb not null default '{}'::jsonb,from_price numeric(10,2),sort_order integer not null default 0,updated_at timestamptz default now());
alter table public.admins enable row level security; alter table public.products enable row level security;
revoke all on public.admins from anon,authenticated; revoke all on public.products from anon,authenticated;
grant select on public.products to anon,authenticated; grant update on public.products to authenticated; grant select on public.admins to authenticated;
drop policy if exists "public read products" on public.products; create policy "public read products" on public.products for select to anon,authenticated using(true);
drop policy if exists "admin membership" on public.admins; create policy "admin membership" on public.admins for select to authenticated using(user_id=auth.uid());
drop policy if exists "admin update products" on public.products; create policy "admin update products" on public.products for update to authenticated using(exists(select 1 from public.admins a where a.user_id=auth.uid())) with check(exists(select 1 from public.admins a where a.user_id=auth.uid()));
