insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict(id) do update set public=true;
drop policy if exists "public product images" on storage.objects; create policy "public product images" on storage.objects for select to public using(bucket_id='product-images');
drop policy if exists "admin upload product images" on storage.objects; create policy "admin upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and exists(select 1 from public.admins a where a.user_id=auth.uid()));
